L6_1 = "LENA_COFFIN_NULL_NULL"
L5_1.m_CharStrID = L6_1
L6_1 = "<color=#ffd34c>\235\132\164, \236\149\140\237\138\184 \236\134\140\235\140\128\236\158\165 \237\155\132\235\176\169 \236\157\180\236\134\161 \237\153\149\236\157\184\237\150\136\236\138\181\235\139\136\235\139\164. \236\160\132\237\136\172 \234\176\128\235\138\165\237\149\156 \235\182\132\235\147\164\236\157\128 \236\160\132\236\132\160\236\156\188\235\161\156 \235\179\181\234\183\128\237\149\180 \236\163\188\236\132\184\236\154\148.</color>"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "<color=#ffd34c>\227\129\175\227\129\132\227\128\129\227\130\162\227\131\171\227\131\136\229\176\143\233\154\138\233\149\183\227\129\174\229\190\140\230\150\185\227\129\184\227\129\174\231\167\187\233\128\129\227\130\146\231\162\186\232\170\141\227\129\151\227\129\190\227\129\151\227\129\159\227\128\130\230\136\166\233\151\152\227\129\140\229\143\175\232\131\189\227\129\170\230\150\185\227\129\175\230\136\166\231\183\154\227\129\171\229\190\169\229\184\176\227\130\146\227\129\138\233\161\152\227\129\132\227\129\151\227\129\190\227\129\153\227\128\130</color>"
L5_1.m_Talk_JPN = L6_1
L6_1 = "<color=#ffd34c>Yes, we have confirmed transportation of the ALT Commander to the rear. All members available for combat, please return to the field.</color>"
L5_1.m_Talk_ENG = L6_1
L6_1 = "<color=#ffd34c>\230\152\175\239\188\140\233\152\191\231\136\190\231\137\185\229\176\143\233\154\138\233\149\183\229\183\178\231\182\147\232\162\171\231\167\187\233\128\129\229\136\176\229\190\140\230\150\185\227\128\130\229\143\175\230\136\176\233\172\165\228\186\186\229\147\161\232\171\139\229\133\168\233\131\168\232\191\148\229\155\158\229\137\141\231\183\154\227\128\130</color>"
L5_1.m_Talk_TWN = L6_1
L6_1 = "<color=#ffd34c>\224\185\131\224\184\138\224\185\136 \224\184\158\224\184\167\224\184\129\224\185\128\224\184\163\224\184\178\224\184\162\224\184\183\224\184\153\224\184\162\224\184\177\224\184\153\224\184\129\224\184\178\224\184\163\224\184\130\224\184\153\224\184\170\224\185\136\224\184\135\224\184\130\224\184\173\224\184\135\224\184\156\224\184\185\224\185\137\224\184\154\224\184\177\224\184\141\224\184\138\224\184\178\224\184\129\224\184\178\224\184\163\224\184\171\224\184\153\224\185\136\224\184\167\224\184\162 ALT \224\185\132\224\184\155\224\184\162\224\184\177\224\184\135\224\185\129\224\184\153\224\184\167\224\184\171\224\184\165\224\184\177\224\184\135\224\185\129\224\184\165\224\185\137\224\184\167 \224\184\170\224\184\161\224\184\178\224\184\138\224\184\180\224\184\129\224\184\151\224\184\184\224\184\129\224\184\132\224\184\153\224\184\151\224\184\181\224\185\136\224\184\158\224\184\163\224\185\137\224\184\173\224\184\161\224\184\149\224\185\136\224\184\173\224\184\170\224\184\185\224\185\137 \224\185\130\224\184\155\224\184\163\224\184\148\224\184\129\224\184\165\224\184\177\224\184\154\224\184\161\224\184\178\224\184\165\224\184\135\224\184\170\224\184\153\224\184\178\224\184\161</color>"
L5_1.m_Talk_THA = L6_1
L6_1 = "<color=#ffd34c>V\195\162ng, ch\195\186ng t\195\180i \196\145\195\163 x\195\161c nh\225\186\173n \196\145\198\176a T\225\187\149ng T\198\176 L\225\187\135nh ALT v\225\187\129 ph\195\173a sau. T\225\186\165t c\225\186\163 th\195\160nh vi\195\170n s\225\186\181n s\195\160ng chi\225\186\191n \196\145\225\186\165u h\195\163y tr\225\187\159 l\225\186\161i chi\225\186\191n tr\198\176\225\187\157ng.</color>"
L5_1.m_Talk_VTN = L6_1
L6_1 = "<color=#ffd34c>\230\152\175\239\188\140\233\152\191\229\176\148\231\137\185\229\176\143\233\152\159\231\154\132\229\176\143\233\152\159\233\149\191\229\183\178\231\187\143\232\162\171\231\167\187\233\128\129\229\136\176\229\144\142\230\150\185\227\128\130\229\143\175\230\136\152\230\150\151\228\186\186\229\145\152\232\175\183\229\133\168\233\131\168\232\191\148\229\155\158\229\137\141\231\186\191\227\128\130</color>"
L5_1.m_Talk_SCN = L6_1
L6_1 = "<color=#ffd34c>Ja, wir haben den Transport der Kommandantin des ALT-Trupps nach hinten best\195\164tigt. Alle f\195\188r den Kampf verf\195\188gbaren Mitglieder, bitte kehren Sie auf das Feld zur\195\188ck.</color>"
L5_1.m_Talk_DEU = L6_1
L6_1 = " <color=#ffd34c>Affirmatif, la commandante de l'escouade ALT a \195\169t\195\169 transf\195\169r\195\169e \195\160 l'arri\195\168re. \195\128 toutes les unit\195\169s en \195\169tat de combattre, reprenez vos positions.</color>"
L5_1.m_Talk_FRA = L6_1
